body {
  font-family: sans-serif;
  text-align: center;
}

#game-container {
  margin: 50px auto;
  width: 80%;
  max-width: 600px;
}

#word-display {
  font-size: 48px;
  font-weight: bold;
  margin-bottom: 20px;
  user-select: none;
}

#input-field {
  font-size: 24px;
  padding: 10px;
}

#score-display {
  margin-top: 20px;
}

#timer-display {
  margin-top: 10px;
}

.difficulty-button {
  margin: 10px;
  padding: 10px 20px;
  background-color: #b6dbff;
  border: none;
  border-radius: 5px;
  cursor: pointer;
}

#settings-container {
  display: none;
  margin-top: 20px;
}

#settings-container > div {
  margin-bottom: 10px;
}

#start-button,
#stop-button {
  margin-top: 20px;
  padding: 10px 20px;
  background-color: #8bc34a;
  border: none;
  border-radius: 5px;
  cursor: pointer;
}

#start-button:disabled,
#stop-button:disabled {
  background-color: #ccc;
  cursor: default;
}
```

