```
#!/usr/bin/perl

use strict;
use warnings;

# Generate edge test cases and random test cases
for (my $i = 0; $i < 15; $i++) {

    # Generate an edge test case for 0, 1, and negative integers
    if ($i < 3) {
        my $n = $i - 1;
        eval {
            my $factorial = factorial($n);
            print "Edge case: $n! => $factorial\n";
        };
        if ($@) {
            print "Edge case: $n! => ERROR\n";
        }
    }

    # Generate random test cases for numbers between 2 and 10
    else {
        my $n = int(rand(9)) + 2;
        my $factorial = factorial($n);
        print "Test case $i: $n! => $factorial\n";
    }
}

# This is the algorithm we're testing
sub factorial {
    my $n = shift;

    # Throw an exception for negative inputs
    if ($n < 0) {
        die "Factorial undefined for negative integers";
    }

    my $result = 1;
    for (my $i = 1; $i <= $n; $i++) {
        $result *= $i;
    }
    return $result;
}
```

