  }
}

// Define a main class for the application
public class Main {
  public static void main(String[] args) {
    // Create a Hibernate configuration object and set the database connection properties
    Configuration cfg = new Configuration();
    cfg.configure("hibernate.cfg.xml");
    SessionFactory factory = cfg.buildSessionFactory();

    // Open a session with the database
    Session session = factory.openSession();

    try {
      // Begin a transaction
      Transaction tx = session.beginTransaction();

      // Insert a new student record into the database
      Student newStudent = new Student();
      newStudent.setName("Alice");
      newStudent.setAge(20);
      session.save(newStudent);

      // Fetch a student record from the database
      Student student = (Student) session.get(Student.class, 1);
      System.out.println(student);

      // Update a student record in the database
